  doc.setTextColor(203, 213, 225); // Slate-300
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.text(branchName + '  •  PC Battlestations  •  PS5  •  Racing Sims', brandX, headerY + 52);
  doc.setTextColor(148, 163, 184); // Slate-400
